import heapq

class TreeNode:
    def __init__(self, key):
        self.key = key
        self.left = None
        self.right = None

def insert(root, key):
    if root is None:
        return TreeNode(key)
    if key < root.key:
        root.left = insert(root.left, key)
    else:
        root.right = insert(root.right, key)
    return root

def in_order(root):
    if root:
        yield from in_order(root.left)
        yield root.key
        yield from in_order(root.right)

root = None
for k in [50, 30, 70, 20, 40]:
    root = insert(root, k)
print(list(in_order(root)))   # [20, 30, 40, 50, 70]

tasks = [5, 1, 8, 3]
heapq.heapify(tasks)
print(heapq.heappop(tasks))   # 1: the smallest comes out first

